323	    /**
324	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
325	     * last two digits of the {@linkplain #getFiscalYear() fiscal year} of the
326	     * (business-day-adjusted) registrationDate, e.g. {@code 'NSW-3C1A9F2B-M27'}.
327	     */
328	    public String getMembershipNumber() {
329	        return this.customerCode + "-M" + String.format("%02d", fiscalYearOf(this.registrationDate) % 100);
330	    }
