332	    /**
333	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where YY is the last two digits of the
334	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the (business-day-adjusted)
335	     * {@link #registrationDate}, e.g. {@code 'FY27'}. The fiscal year starts on 1 July and is
336	     * labelled by the calendar year in which it ends.
337	     */
338	    public String getFiscalYear() {
339	        return "FY" + String.format("%02d", fiscalYearOf(this.registrationDate) % 100);
340	    }
