342	    /**
343	     * The fiscal year that contains the given date, identified by the calendar year in which it
344	     * ends. The fiscal year starts on 1 July, so a date in July through December belongs to the
345	     * fiscal year ending in the following calendar year, while a date in January through June
346	     * belongs to the fiscal year ending in the same calendar year.
347	     */
348	    private static int fiscalYearOf(LocalDate date) {
349	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
350	    }
351	
352	    /**
353	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) computed over the decimal digits
354	     * contained in the owner's {@link #customerCode}.
355	     */
356	    public int getCheckDigit() {
357	        return luhnCheckDigit(this.customerCode);
358	    }
359	
360	    /**
361	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
362	     * contained in {@code value}. Reading the digits right to left, every second one is
363	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
364	     * digits are summed, and the check digit is the amount that must be added to that sum to
365	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
366	     * the digit is taken over exactly the digits the string carries.
367	     */
368	    private static int luhnCheckDigit(String value) {
369	        int sum = 0;
370	        boolean doubling = true;
371	        for (int i = value.length() - 1; i >= 0; i--) {
372	            char c = value.charAt(i);
373	            if (c < '0' || c > '9') {
374	                continue;
375	            }
376	            int digit = c - '0';
377	            if (doubling) {
378	                digit *= 2;
379	                if (digit > 9) {
380	                    digit -= 9;
381	                }
382	            }
383	            sum += digit;
384	            doubling = !doubling;
385	        }
386	        return (10 - (sum % 10)) % 10;
387	    }
