389	    /** Fixed city-to-region table used to derive an owner's locality. */
390	    private static final Map<String, String> CITY_REGION = Map.of(
391	        "Sydney", "NSW",
392	        "Melbourne", "VIC",
393	        "Brisbane", "QLD");
394	
395	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
396	    public static final String UNKNOWN_REGION = "UNKNOWN";
397	
398	    /**
399	     * The canonical region for a city, derived from the fixed city-to-region table
400	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
401	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
402	     * source of the city-to-region mapping, shared by every rule that is keyed by
403	     * region so the mapping is never re-derived elsewhere.
404	     */
405	    public static String regionOf(String city) {
406	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
407	    }
408	
409	    /**
410	     * The owner's locality: the {@code <REGION>} component of the {@link #getCustomerCode()
411	     * customerCode} (its prefix up to the first {@code '-'}), which is the region derived from
412	     * the owner's postcode at creation ({@link #UNKNOWN_REGION} when the postcode maps to no
413	     * known region). Locality is read from the region-and-hash identity so it never re-derives
414	     * a region of its own; it is {@link #UNKNOWN_REGION} for an owner that has no customerCode.
415	     */
416	    public String getLocality() {
417	        if (this.customerCode == null) {
418	            return UNKNOWN_REGION;
419	        }
420	        int dash = this.customerCode.indexOf('-');
421	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
422	    }
423	
424	    /** Fixed region-to-timezone table, mapping a region to its IANA timezone name. */
425	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
426	        "NSW", "Australia/Sydney",
427	        "VIC", "Australia/Melbourne",
428	        "QLD", "Australia/Brisbane");
429	
430	    /**
431	     * The owner's timezone: the IANA name for this owner's {@linkplain #getLocality() locality},
432	     * looked up in the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
433	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or {@code null} when
434	     * the locality maps to no known region (e.g. {@link #UNKNOWN_REGION}). It reads the locality
435	     * rather than re-deriving a region so the timezone shares the owner's single region identity.
436	     */
437	    public String getTimezone() {
438	        return REGION_TIMEZONE.get(getLocality());
439	    }
440	
441	    /**
442	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'},
443	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. TIER is
444	     * {@code 'PREMIUM'} when {@linkplain #getMembershipLevel() membershipLevel} is 3 or more,
445	     * otherwise {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's
446	     * {@linkplain #getLocality() locality} is a known region (NSW, VIC or QLD), otherwise
447	     * {@code 'REGIONAL'}. It reads the locality against the shared region table so it never
448	     * re-derives a region of its own.
449	     */
450	    public String getOwnerSegment() {
451	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
452	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
453	        return tier + "_" + area;
454	    }
455	
456	    /**
457	     * The region derived from this owner's postcode alone: the region whose fixed
458	     * {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the postcode, or {@code null}
459	     * when the postcode is absent, not four digits, or in no known range. This is the {@code <REGION>}
460	     * component built into the owner's customer code at creation and, through it, the source of the
461	     * owner's {@linkplain #getLocality() locality}. It is the single place a region is read from an
462	     * owner's postcode, so every rule keyed by the postcode-derived region shares one derivation.
463	     */
464	    public String getRegion() {
465	        return regionOfPostcode(this.postcode);
466	    }
467	
468	    /**
469	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
470	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
471	     * no known range.
472	     */
473	    private static String regionOfPostcode(String postcode) {
474	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
475	            return null;
476	        }
477	        int value = Integer.parseInt(postcode);
478	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
479	            int[] range = entry.getValue();
480	            if (value >= range[0] && value <= range[1]) {
481	                return entry.getKey();
482	            }
483	        }
484	        return null;
485	    }
486	
487	    /**
488	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
489	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
490	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
491	     */
492	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
493	        "NSW", new int[] {2000, 2099},
494	        "VIC", new int[] {3000, 3099},
495	        "QLD", new int[] {4000, 4099});
496	
497	    /**
498	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
499	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
500	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
501	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
502	     * city with no known region accepts any 4-digit postcode.
503	     */
504	    public boolean isPostcodeValid() {
505	        if (this.postcode == null) {
506	            return true;
507	        }
508	        if (!this.postcode.matches("[0-9]{4}")) {
509	            return false;
510	        }
511	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
512	        if (range == null) {
513	            return true;
514	        }
515	        int value = Integer.parseInt(this.postcode);
516	        return value >= range[0] && value <= range[1];
517	    }
518	
519	    /**
520	     * The national (subscriber) digit count required by each known country calling code, keyed by
521	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
522	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
523	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
524	     * re-derived elsewhere.
525	     */
526	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
527	        "1", 10,
528	        "61", 9);
529	
530	    /**
531	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
532	     * E.164 digit string, choosing the longest matching code known to
533	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
534	     * country code. This is the single place a country code is read from an E.164 number, so every
535	     * rule keyed by that code shares one derivation.
536	     */
537	    private static String countryCodeOf(String e164Digits) {
538	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
539	            .filter(e164Digits::startsWith)
540	            .max(Comparator.comparingInt(String::length))
541	            .orElse(null);
542	    }
543	
544	    /**
545	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
546	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
547	     * known code wins; a number whose country code is not recognised passes this check (its length is
548	     * then governed only by the general E.164 bound), while a recognised code must be followed by
549	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
550	     */
551	    public static boolean hasValidNationalLength(String e164Digits) {
552	        String countryCode = countryCodeOf(e164Digits);
553	        if (countryCode == null) {
554	            return true;
555	        }
556	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
557	    }
558	
559	    /**
560	     * The owner's membership points: they start at 0, gain 2 when an email is present, gain 1 when
561	     * namesakeCount is 0, gain 2 for a {@linkplain #hasLargeHousehold() household of 3 or more}, and
562	     * gain 3 when the owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one
563	     * elapsed fiscal year. The email, namesake and household factors are available on creation; the
564	     * tenure factor is reached only once at least one fiscal-year boundary has passed.
565	     */
566	    public Integer getMembershipPoints() {
567	        int points = 0;
568	        if (hasEmail()) {
569	            points += 2;
570	        }
571	        if (hasNoNamesakes()) {
572	            points += 1;
573	        }
574	        if (hasLargeHousehold()) {
575	            points += 2;
576	        }
577	        if (hasQualifyingTenure()) {
578	            points += 3;
579	        }
580	        return points;
581	    }
582	
583	    /**
584	     * The owner's membership level, a number from 1 to 4. For an owner created through the
585	     * creation pipeline this is the value assigned and stored at creation time; an owner that
586	     * carries no assigned level (e.g. seed data, or an owner not created through that pipeline)
587	     * reports its {@linkplain #getBaseMembershipLevel() base level} derived from its
588	     * membershipPoints. This is the single value read by the API for an owner's membership level.
589	     */
590	    public Integer getMembershipLevel() {
591	        return this.membershipLevel != null ? this.membershipLevel : getBaseMembershipLevel();
592	    }
593	
594	    public void setMembershipLevel(Integer membershipLevel) {
595	        this.membershipLevel = membershipLevel;
596	    }
597	
598	    /**
599	     * The owner's base membership level, a number from 1 to 4 derived directly from
600	     * {@linkplain #getMembershipPoints() membershipPoints}: level 1 for 0-1 points, level 2 for 2-3,
601	     * level 3 for 4-5, and level 4 for 6 or more. This is the level the creation pipeline starts
602	     * from when it assigns the owner's stored {@linkplain #getMembershipLevel() membershipLevel}.
603	     */
604	    public Integer getBaseMembershipLevel() {
605	        int points = getMembershipPoints();
606	        if (points >= 6) {
607	            return 4;
608	        }
609	        if (points >= 4) {
610	            return 3;
611	        }
612	        if (points >= 2) {
613	            return 2;
614	        }
615	        return 1;
616	    }
617	
618	    /**
619	     * Whether this owner belongs to a household of three or more: its {@link #getHouseholdSize()
620	     * householdSize} is {@code 3} or greater. A {@code null} householdSize, meaning the size is not
621	     * known, is treated as not a large household.
622	     */
623	    private boolean hasLargeHousehold() {
624	        return this.householdSize != null && this.householdSize >= 3;
625	    }
626	
627	    /**
628	     * Whether this owner has an email on record: a non-{@code null}, non-empty {@link #getEmail()
629	     * email}. This is the single source of the "has an email" test, shared by every rule keyed by
630	     * email presence so the check is never re-derived elsewhere.
631	     */
632	    private boolean hasEmail() {
633	        return this.email != null && !this.email.isEmpty();
634	    }
635	
636	    /**
637	     * Whether this owner's name is unique in the clinic: its {@link #getNamesakeCount() namesakeCount}
638	     * is {@code 0} (no other owner shares the name). A {@code null} namesakeCount, meaning the count is
639	     * not known, is treated as not unique.
640	     */
641	    private boolean hasNoNamesakes() {
642	        return this.namesakeCount != null && this.namesakeCount == 0;
643	    }
644	
645	    /**
646	     * Whether this owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one elapsed
647	     * fiscal year. A newly created owner (zero elapsed fiscal years) does not qualify; the threshold
648	     * is crossed only once at least one fiscal-year boundary has passed since registration.
649	     */
650	    private boolean hasQualifyingTenure() {
651	        return this.getTenureFiscalYears() >= 1;
652	    }
653	
654	    /**
655	     * The owner's tenure in elapsed fiscal years: the number of fiscal-year boundaries between the
656	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the {@link #registrationDate} and the
657	     * fiscal year of the current date, or {@code 0} when the registrationDate is not yet set (a newly
658	     * created owner has zero tenure). Never negative.
659	     */
660	    public long getTenureFiscalYears() {
661	        if (this.registrationDate == null) {
662	            return 0;
663	        }
664	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
665	    }
666	
667	    /**
668	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
669	     * otherwise {@code 'PHONE'}.
670	     */
671	    public String getContactPreference() {
672	        return hasEmail() ? "EMAIL" : "PHONE";
673	    }
674	
675	    /**
676	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
677	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
678	     * the national digits grouped into threes from the left separated by spaces,
679	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
680	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
681	     * E.164 form, or carries no known country code.
682	     */
683	    public String getTelephoneDisplay() {
684	        if (this.telephone == null || !this.telephone.startsWith("+")) {
685	            return this.telephone;
686	        }
687	        String digits = this.telephone.substring(1);
688	        String countryCode = countryCodeOf(digits);
689	        if (countryCode == null) {
690	            return this.telephone;
691	        }
692	        String national = digits.substring(countryCode.length());
693	        StringBuilder groups = new StringBuilder();
694	        for (int i = 0; i < national.length(); i += 3) {
695	            if (groups.length() > 0) {
696	                groups.append(' ');
697	            }
698	            groups.append(national, i, Math.min(i + 3, national.length()));
699	        }
700	        return "+" + countryCode + " " + groups;
701	    }
702	
703	    /**
704	     * The owner's identity key: the single derived value used for duplicate detection. It is the
705	     * lower-case hex SHA-256 (64 characters) of the normalized (E.164) telephone, the email
706	     * (already lower-cased, or the empty string when absent) and the {@linkplain #soundex(String)
707	     * soundex} of the lastName, joined with {@code '|'} before hashing, e.g. the digest of
708	     * {@code '+61412345678|jane@example.test|J500'}. Two owners are duplicates, and the second is
709	     * rejected with {@code 409}, only when their whole identity keys are equal.
710	     */
711	    public String getIdentityKey() {
712	        String telephonePart = this.telephone == null ? "" : this.telephone;
713	        String emailPart = this.email == null ? "" : this.email;
714	        String soundexPart = soundex(this.getLastName());
715	        return HashUtils.sha256Hex(telephonePart + "|" + emailPart + "|" + soundexPart);
716	    }
717	
718	    /**
719	     * The American Soundex code of {@code name}: its first letter followed by three digits encoding
720	     * the remaining consonant sounds ({@code b,f,p,v -> 1}; {@code c,g,j,k,q,s,x,z -> 2};
721	     * {@code d,t -> 3}; {@code l -> 4}; {@code m,n -> 5}; {@code r -> 6}; vowels and {@code h,w,y}
722	     * are not coded). Adjacent letters with the same code, and same-coded letters separated only by
723	     * {@code h} or {@code w}, contribute a single digit; a vowel between two same-coded letters
724	     * keeps both. The result is right-padded with zeros and truncated to four characters. Non-letters
725	     * are ignored, and a {@code null} or letter-free name yields the empty string. Used to build the
726	     * owner's {@link #getIdentityKey() identity key} and to group households by surname sound.
727	     */
728	    public static String soundex(String name) {
729	        if (name == null) {
730	            return "";
731	        }
732	        String letters = name.toUpperCase().replaceAll("[^A-Z]", "");
733	        if (letters.isEmpty()) {
734	            return "";
735	        }
736	        StringBuilder code = new StringBuilder();
737	        code.append(letters.charAt(0));
738	        char previous = soundexDigit(letters.charAt(0));
739	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
740	            char c = letters.charAt(i);
741	            char digit = soundexDigit(c);
742	            if (digit != '0' && digit != previous) {
743	                code.append(digit);
744	            }
745	            if (c != 'H' && c != 'W') {
746	                previous = digit;
747	            }
748	        }
749	        while (code.length() < 4) {
750	            code.append('0');
751	        }
752	        return code.toString();
753	    }
754	
755	    /**
756	     * The Soundex digit for a single upper-case letter (see {@link #soundex(String)}), or
757	     * {@code '0'} for a letter that is not coded (a vowel, or {@code h}, {@code w} or {@code y}).
758	     */
759	    private static char soundexDigit(char c) {
760	        switch (c) {
761	            case 'B': case 'F': case 'P': case 'V':
762	                return '1';
763	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
764	                return '2';
765	            case 'D': case 'T':
766	                return '3';
767	            case 'L':
768	                return '4';
769	            case 'M': case 'N':
770	                return '5';
771	            case 'R':
772	                return '6';
773	            default:
774	                return '0';
775	        }
776	    }
777	
778	    protected Set<Pet> getPetsInternal() {
779	        if (this.pets == null) {
780	            this.pets = new HashSet<>();
781	        }
782	        return this.pets;
783	    }
784	
785	    protected void setPetsInternal(Set<Pet> pets) {
786	        this.pets = pets;
787	    }
788	
789	    public List<Pet> getPets() {
790	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
791	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
792	        return Collections.unmodifiableList(sortedPets);
793	    }
794	
795	    public void setPets(List<Pet> pets) {
796	        this.pets = new HashSet<>(pets);
797	    }
798	
799	    public void addPet(Pet pet) {
800	        getPetsInternal().add(pet);
801	        pet.setOwner(this);
802	    }
803	
804	    /**
805	     * Return the Pet with the given name, or null if none found for this Owner.
806	     *
807	     * @param name to test
808	     * @return true if pet name is already in use
809	     */
810	    public Pet getPet(String name) {
811	        return getPet(name, false);
812	    }
813	
814	    /**
815	     * Return the Pet with the given name, or null if none found for this Owner.
816	     *
817	     * @param name to test
818	     * @return true if pet name is already in use
819	     */
820	    public Pet getPet(String name, boolean ignoreNew) {
821	        name = name.toLowerCase();
822	        for (Pet pet : getPetsInternal()) {
823	            if (!ignoreNew || !pet.isNew()) {
824	                String compName = pet.getName();
825	                compName = compName.toLowerCase();
826	                if (compName.equals(name)) {
827	                    return pet;
828	                }
829	            }
830	        }
831	        return null;
832	    }
833	
834	    public Pet getPet(Integer petId) {
835	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
836	    }
837	
838	    @Override
839	    public String toString() {
840	        return new ToStringCreator(this)
841	
842	            .append("id", this.getId())
843	            .append("new", this.isNew())
844	            .append("lastName", this.getLastName())
845	            .append("firstName", this.getFirstName())
846	            .append("address", this.address)
847	            .append("city", this.city)
848	            .append("telephone", this.telephone)
849	            .append("email", this.email)
850	            .toString();
851	    }
852	}
