70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
74	
75	    /**
76	     * Serializes {@link OwnerCreatedEvent structured audit events} to their JSON form. Stateless and
77	     * thread-safe, so a single shared instance serves every create.
78	     */
79	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
80	
81	    /**
82	     * Monotonically increasing sequence stamped onto each {@link OwnerCreatedEvent OWNER_CREATED}
83	     * event, so the ordering of creates is recoverable from the audit stream alone. Shared across all
84	     * creates (hence {@code static}) and incremented once per emitted event.
85	     */
86	    private static final AtomicLong AUDIT_SEQ = new AtomicLong();
87	
88	    /**
89	     * Immutable structured audit event emitted (as JSON) alongside the human-readable audit line when
90	     * an owner is created. Its {@code customerCode} component carries the owner's <em>current primary
91	     * identifier</em>: today that is the {@link Owner#getCustomerCode() customerCode}, and when the
92	     * customerCode is later unified into the memberId this event will carry the memberId instead — so
93	     * downstream consumers always read the owner's primary identifier from the same event.
94	     *
95	     * <p>The component order matches the serialized field order
96	     * {@code {seq, ownerId, customerCode, membershipLevel, event}}.
97	     */
98	    private record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
99	                                     Integer membershipLevel, String event) {
100	
101	        private static final String OWNER_CREATED = "OWNER_CREATED";
102	
103	        static OwnerCreatedEvent of(long seq, Owner owner) {
104	            return new OwnerCreatedEvent(seq, owner.getId(), primaryIdentifier(owner),
105	                owner.getMembershipLevel(), OWNER_CREATED);
106	        }
107	
108	        /**
109	         * The owner's current primary identifier. Today the owner is identified by its
110	         * {@link Owner#getCustomerCode() customerCode}; when that is unified into the memberId this
111	         * single method changes to return the memberId and the event follows automatically.
112	         */
113	        private static String primaryIdentifier(Owner owner) {
114	            return owner.getCustomerCode();
115	        }
116	    }
117	
118	    /**
119	     * The HTTP request header a client may send to make a create idempotent. When a create repeats
120	     * with a key already seen, the originally created owner is returned instead of a duplicate.
121	     */
122	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
123	
124	    /**
125	     * Remembers, per {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key}, the id of the owner that key's
126	     * first successful create produced, so a repeat of that create can return the same owner rather
127	     * than creating a duplicate.
128	     */
129	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
130	
131	    /**
132	     * Fixed public-holiday calendar. A registration date that lands on one of these dates is rolled
133	     * forward to the next non-holiday business day, in the same way weekends are.
134	     */
135	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
136	        LocalDate.of(2026, 1, 1),
137	        LocalDate.of(2026, 1, 26),
138	        LocalDate.of(2026, 4, 25),
139	        LocalDate.of(2026, 12, 25),
140	        LocalDate.of(2026, 12, 28));
141	
142	    private final ClinicService clinicService;
143	
144	    private final OwnerMapper ownerMapper;
145	
146	    private final PetMapper petMapper;
147	
148	    private final VisitMapper visitMapper;
149	
150	    private final AddressNormalizer addressNormalizer;
151	
152	    public OwnerRestControllerV1(ClinicService clinicService,
153	                                 OwnerMapper ownerMapper,
154	                                 PetMapper petMapper,
155	                                 VisitMapper visitMapper,
156	                                 AddressNormalizer addressNormalizer) {
157	        this.clinicService = clinicService;
158	        this.ownerMapper = ownerMapper;
159	        this.petMapper = petMapper;
160	        this.visitMapper = visitMapper;
161	        this.addressNormalizer = addressNormalizer;
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
167	        Collection<Owner> owners;
168	        if (lastName != null) {
169	            owners = this.clinicService.findOwnerByLastName(lastName);
170	        } else {
171	            owners = this.clinicService.findAllOwners();
172	        }
173	        if (owners.isEmpty()) {
174	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
175	        }
176	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
182	        Owner owner = this.clinicService.findOwnerById(ownerId);
183	        if (owner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
192	        String idempotencyKey = currentIdempotencyKey();
193	        if (idempotencyKey != null) {
194	            Integer existingId = idempotentCreates.get(idempotencyKey);
195	            if (existingId != null) {
196	                Owner existing = this.clinicService.findOwnerById(existingId);
197	                if (existing != null) {
198	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
199	                }
200	            }
201	        }
202	
203	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
204	
205	        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
206	            && response.getBody() != null && response.getBody().getId() != null) {
207	            idempotentCreates.put(idempotencyKey, response.getBody().getId());
208	        }
209	        return response;
210	    }
211	
212	    /**
213	     * The non-blank {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key} header of the request currently
214	     * being handled, or {@code null} when the request carries no such header (or no request is bound
215	     * to the current thread). Used to make a repeated create return the originally created owner.
216	     */
217	    private String currentIdempotencyKey() {
218	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
219	            return null;
220	        }
221	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
222	        return (key == null || key.isBlank()) ? null : key;
223	    }
224	
225	    /**
226	     * Run the full owner-creation pipeline for a submitted {@link OwnerFieldsDto} and build its
227	     * response. The submitted fields are mapped to an {@link Owner}, which is
228	     * {@link #normalizeAndValidate(Owner) normalized and validated}, checked against the
229	     * {@link #isDailyLimitReached(LocalDate) daily creation limit}, {@link #assignHousehold(Owner)
230	     * assigned its household} and screened for {@link #checkForConflicts(Owner) conflicts};
231	     * a surviving owner then has its {@link #assignDerivedAttributes(Owner, boolean) derived
232	     * attributes} assigned, is persisted and audited. Returns the {@link #created(Owner) 201 Created}
233	     * response for the persisted owner, or the {@link HttpStatus} the create must fail with
234	     * ({@code 400 Bad Request}, {@code 429 Too Many Requests} or {@code 409 Conflict}) when the owner
235	     * cannot be created.
236	     */
237	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
238	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
239	
240	        HttpStatus invalid = normalizeAndValidate(owner);
241	        if (invalid != null) {
242	            return new ResponseEntity<>(invalid);
243	        }
244	        if (isDailyLimitReached(owner.getRegistrationDate())) {
245	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
246	        }
247	
248	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
249	        assignHousehold(owner);
250	
251	        HttpStatus conflict = checkForConflicts(owner);
252	        if (conflict != null) {
253	            return new ResponseEntity<>(conflict);
254	        }
255	
256	        assignDerivedAttributes(owner, sharesHousehold);
257	        this.clinicService.saveOwner(owner);
258	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
259	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
260	            owner.getMembershipLevel(), owner.getMembershipNumber());
261	        emitOwnerCreatedEvent(owner);
262	        return created(owner);
263	    }
