276	    /**
277	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
278	     * rejected. The owner's {@link #normalizeAddress(Owner) address is normalized} (a missing address
279	     * is rejected), its telephone is converted to E.164 (an unconvertible number is rejected), its
280	     * postcode is checked against its city's region, a registration date in the future is rejected,
281	     * and the effective registration date (the supplied one, or today when none was given) is rolled
282	     * onto a business day and stored back on the owner. Returns {@code null} once the owner is valid
283	     * and normalized, or the {@link HttpStatus} the create must fail with ({@code 400 Bad Request})
284	     * otherwise.
285	     */
286	    private HttpStatus normalizeAndValidate(Owner owner) {
287	        if (!normalizeAddress(owner)) {
288	            return HttpStatus.BAD_REQUEST;
289	        }
290	        String telephone = toE164(owner.getTelephone());
291	        if (telephone == null) {
292	            return HttpStatus.BAD_REQUEST;
293	        }
294	        owner.setTelephone(telephone);
295	        if (isDisposableEmail(owner.getEmail())) {
296	            return HttpStatus.BAD_REQUEST;
297	        }
298	        if (!owner.isPostcodeValid()) {
299	            return HttpStatus.BAD_REQUEST;
300	        }
301	        if (owner.getRegistrationDate() != null
302	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
303	            return HttpStatus.BAD_REQUEST;
304	        }
305	        LocalDate effectiveDate = owner.getRegistrationDate() != null
306	            ? owner.getRegistrationDate() : LocalDate.now();
307	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
308	        return null;
309	    }
