311	    /**
312	     * Normalize the owner's supplied address into its canonical stored form and report whether an
313	     * address was supplied at all. The owner may supply its address either as the structured
314	     * {@code addressLine1}/{@code addressLine2} fields or as the flat {@code address} field, which is
315	     * kept for backward compatibility; the structured form is preferred whenever a non-blank
316	     * {@code addressLine1} is present. Each supplied field is run through the {@link AddressNormalizer}
317	     * (trimmed, whitespace-collapsed, upper-cased, common street-type abbreviations expanded). When the
318	     * structured form is used, the normalized {@code addressLine1} and {@code addressLine2} are stored
319	     * back and the composed {@link Owner#getAddress() address} becomes the normalized
320	     * {@code addressLine1} with a single space and the normalized {@code addressLine2} appended when an
321	     * {@code addressLine2} is present; when the flat form is used, the normalized flat address is
322	     * stored and no structured lines are kept. Returns {@code true} once a non-blank address has been
323	     * normalized and stored, or {@code false} when neither form supplied an address, in which case the
324	     * create must be rejected with {@code 400 Bad Request}.
325	     */
326	    private boolean normalizeAddress(Owner owner) {
327	        String line1 = addressNormalizer.normalize(owner.getAddressLine1());
328	        if (!line1.isEmpty()) {
329	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
330	            owner.setAddressLine1(line1);
331	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
332	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
333	            return true;
334	        }
335	        String address = addressNormalizer.normalize(owner.getAddress());
336	        if (address.isEmpty()) {
337	            return false;
338	        }
339	        owner.setAddressLine1(null);
340	        owner.setAddressLine2(null);
341	        owner.setAddress(address);
342	        return true;
343	    }
