352	    /**
353	     * Whether the given email is hosted on a {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable}
354	     * domain. The email is optional, so a {@code null} or empty email is not disposable; otherwise
355	     * the domain (the part after the last {@code '@'}, compared case-insensitively) is matched
356	     * against the blocklist.
357	     */
358	    private boolean isDisposableEmail(String email) {
359	        if (email == null || email.isEmpty()) {
360	            return false;
361	        }
362	        int at = email.lastIndexOf('@');
363	        if (at < 0) {
364	            return false;
365	        }
366	        String domain = email.substring(at + 1).toLowerCase();
367	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
368	    }
