383	    /**
384	     * Whether the owner clashes with an owner that already exists, and the {@link HttpStatus} the
385	     * create must fail with when it does. An owner is rejected with {@code 409 Conflict} when it
386	     * {@linkplain #isDuplicateIdentity(Owner) duplicates an existing owner's identity key} or when
387	     * its {@link #isCityAtCapacity(String) city is already at capacity}. Sharing a household (the
388	     * same surname sound and postcode) but with a different identity key is not a conflict: such an
389	     * owner is admitted and later {@linkplain #findSoftDuplicate(Owner) flagged as a possible
390	     * duplicate}. Returns {@code null} when the owner clashes with nothing and may be created.
391	     */
392	    private HttpStatus checkForConflicts(Owner owner) {
393	        if (isDuplicateIdentity(owner)) {
394	            return HttpStatus.CONFLICT;
395	        }
396	        if (isCityAtCapacity(owner.getCity())) {
397	            return HttpStatus.CONFLICT;
398	        }
399	        return null;
