402	    /**
403	     * Whether an existing owner already carries this owner's {@link Owner#getIdentityKey() identity
404	     * key}. This is the single hard-duplicate rule: two owners are duplicates exactly when their
405	     * identity keys are equal, and the second is rejected with {@code 409 Conflict}. Like the other
406	     * identity rules it considers only the {@linkplain #activeOwners() active owners}, so an owner
407	     * flagged {@linkplain Owner#isDeleted() deleted} never triggers a duplicate. The email-domain
408	     * blocklist is applied earlier, during {@link #normalizeAndValidate(Owner) validation}, so a
409	     * disposable-email owner is rejected before it reaches this check.
410	     */
411	    private boolean isDuplicateIdentity(Owner owner) {
412	        String identityKey = owner.getIdentityKey();
413	        return activeOwners().stream()
414	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
415	    }
