428	    /**
429	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
430	     * {@link #customerCode(Owner) customerCode}, {@link #namesakeCount(String, String) namesakeCount},
431	     * {@link #isBulkSignup(LocalDate) bulk-signup warning}, {@link #isCityApproachingCapacity(String)
432	     * capacity warning}, {@link #householdSize(String)
433	     * householdSize} and {@link #membershipLevel(Owner) membershipLevel}. Each is computed from the
434	     * owner's own fields together with the owners already present, so this runs after the owner has
435	     * been validated and has passed the duplicate and capacity checks, and immediately before it is
436	     * persisted.
437	     */
438	    private void assignDerivedAttributes(Owner owner, boolean sharesHousehold) {
439	        owner.setCustomerCode(customerCode(owner));
440	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
441	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
442	        owner.setCapacityWarning(isCityApproachingCapacity(owner.getCity()));
443	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
444	        owner.setMembershipLevel(membershipLevel(owner));
445	        assignPossibleDuplicate(owner, sharesHousehold);
446	    }
