448	    /**
449	     * The membership level to assign a newly created owner and store on it as its
450	     * {@link Owner#getMembershipLevel() membershipLevel}: the owner's own
451	     * {@linkplain Owner#getBaseMembershipLevel() base level} derived from its membershipPoints,
452	     * capped so it cannot exceed one above the current maximum membershipLevel among the owner's
453	     * existing {@linkplain #householdMembers(String) household members}. With no existing household
454	     * member no cap applies and the base level is used as-is. This is the single place the stored
455	     * membership level is derived; it runs during {@link #assignDerivedAttributes(Owner, boolean)},
456	     * after the owner has passed the duplicate and capacity checks and so has its household members
457	     * available to it.
458	     */
459	    private Integer membershipLevel(Owner owner) {
460	        int base = owner.getBaseMembershipLevel();
461	        Collection<Owner> members = householdMembers(owner.getHouseholdId());
462	        if (members.isEmpty()) {
463	            return base;
464	        }
465	        int householdMax = members.stream()
466	            .mapToInt(Owner::getMembershipLevel)
467	            .max()
468	            .getAsInt();
469	        return Math.min(base, householdMax + 1);
470	    }
