472	    /**
473	     * Flag a newly created owner as a possible (soft) duplicate. An owner that declares it shares a
474	     * household ({@code sharesHousehold}) is a declared household member, not a suspected duplicate,
475	     * so it is never flagged. Otherwise it is flagged only when it is a soft match of an existing
476	     * owner as determined by {@link #findSoftDuplicate(Owner)}. When such an owner exists the new owner is flagged with
477	     * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that owner's id;
478	     * otherwise {@code possibleDuplicate = false} and no matching id is recorded.
479	     */
480	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
481	        Owner match = sharesHousehold ? null : findSoftDuplicate(owner);
482	        owner.setPossibleDuplicate(match != null);
483	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
484	    }
