486	    /**
487	     * The owners a newly created owner is checked against by the duplicate and identity rules:
488	     * the {@link #householdMembers(String) household} membership and {@link #findSoftDuplicate(Owner)
489	     * soft-duplicate} checks, the {@link #customerCode(Owner) customerCode} de-duplication and the
490	     * {@link #namesakeCount(String, String) namesake} count. This is the single place that scope is
491	     * defined, so every one of those rules considers exactly the same set of owners; it spans every
492	     * owner the clinic holds except those flagged {@linkplain Owner#isDeleted() deleted}, which a
493	     * soft delete retains but excludes from duplicate and identity detection.
494	     */
495	    private Collection<Owner> activeOwners() {
496	        return this.clinicService.findAllOwners().stream()
497	            .filter(owner -> !owner.isDeleted())
498	            .collect(Collectors.toList());
499	    }
500	
501	    /**
502	     * The existing owner this owner softly duplicates, or {@code null} when there is none. A soft
503	     * match is an existing owner whose {@link Owner#getIdentityKey() identity key} differs from this
504	     * owner's (so it is not already a hard duplicate) but whose lastName has the same
505	     * {@link Owner#soundex(String) soundex} and whose postcode matches; the earliest such owner (by
506	     * id) is returned. Two owners sharing a surname sound and postcode but differing in telephone (or
507	     * email) therefore surface here as a soft match rather than being rejected. A postcode is required
508	     * for a soft match, so an owner without a postcode never matches.
509	     */
510	    private Owner findSoftDuplicate(Owner owner) {
511	        if (owner.getPostcode() == null) {
512	            return null;
513	        }
514	        String candidateSoundex = Owner.soundex(owner.getLastName());
515	        String identityKey = owner.getIdentityKey();
516	        return activeOwners().stream()
517	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
518	            .filter(existing -> Owner.soundex(existing.getLastName()).equals(candidateSoundex))
519	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
520	            .min(Comparator.comparingInt(Owner::getId))
521	            .orElse(null);
522	    }
523	
524	    /**
525	     * Build the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
526	     * where REGION is the region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION}
527	     * when the postcode is absent or maps to no known region) and HASH8 is the first 8 upper-case
528	     * hex characters of the SHA-256 of the normalized (E.164) telephone concatenated with the
529	     * lastName (e.g. {@code 'NSW-3C1A9F2B'}). This is the single source of the owner's identity:
530	     * every value built from the customer code (the membership number and its check digit) and the
531	     * owner's locality are derived from it.
532	     *
533	     * <p>When the computed code collides with an existing owner's {@code customerCode}, a
534	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes the code
535	     * unique, and the de-duplicated code is returned.
536	     */
537	    private String customerCode(Owner owner) {
538	        String region = owner.getRegion() != null ? owner.getRegion() : Owner.UNKNOWN_REGION;
539	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName()).substring(0, 8);
540	        String base = region + "-" + hash8;
541	
542	        Set<String> existingCodes = activeOwners().stream()
543	            .map(Owner::getCustomerCode)
544	            .filter(Objects::nonNull)
545	            .collect(Collectors.toSet());
546	
547	        if (!existingCodes.contains(base)) {
548	            return base;
549	        }
550	        int n = 2;
551	        while (existingCodes.contains(base + "-" + n)) {
552	            n++;
553	        }
554	        return base + "-" + n;
555	    }
