557	    /**
558	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
559	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
560	     * (business-day) registration date of the owner being created, so owners are counted per
561	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
562	     */
563	    private boolean isDailyLimitReached(LocalDate day) {
564	        long count = this.clinicService.findAllOwners().stream()
565	            .filter(existing -> day.equals(existing.getRegistrationDate()))
566	            .count();
567	        return count >= 100;
568	    }
