570	    /**
571	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
572	     * more than 80 owners have already been created for the given business day. Counts the owners
573	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
574	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
575	     * warning.
576	     */
577	    private boolean isBulkSignup(LocalDate day) {
578	        long count = this.clinicService.findAllOwners().stream()
579	            .filter(existing -> day.equals(existing.getRegistrationDate()))
580	            .count();
581	        return count > 80;
