584	    /**
585	     * Roll a registration date forward onto a business day: when it falls on a Saturday, Sunday or a
586	     * listed public holiday, advance it to the next non-holiday weekday; an ordinary weekday is
587	     * returned unchanged.
588	     */
589	    private LocalDate toBusinessDay(LocalDate date) {
590	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
591	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
592	            || PUBLIC_HOLIDAYS.contains(date)) {
593	            date = date.plusDays(1);
594	        }
595	        return date;
596	    }
