598	    /**
599	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
600	     * more owners. Cities are compared case-insensitively.
601	     */
602	    private boolean isCityAtCapacity(String city) {
603	        return cityOwnerCount(city) >= 50;
