619	     * The number of existing owners in the given city, compared case-insensitively. Counted over the
620	     * owners present before this create.
621	     */
622	    private long cityOwnerCount(String city) {
623	        return this.clinicService.findAllOwners().stream()
624	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
