628	    /**
629	     * The number of existing owners that already share the given firstName and lastName,
630	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
631	     * whitespace runs collapsed). Counted over the owners present before this create.
632	     */
633	    private int namesakeCount(String firstName, String lastName) {
634	        String candidateFirstName = normalizeName(firstName);
635	        String candidateLastName = normalizeName(lastName);
636	        return (int) activeOwners().stream()
637	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
638	                && normalizeName(existing.getLastName()).equals(candidateLastName))
639	            .count();
