642	    /**
643	     * The number of members in this owner's household after this create: the count of existing
644	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
645	     * created. An owner with no household ({@code householdId == null}) is a household of one.
646	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
647	     * does not depend on the order in which household members were created.
648	     */
649	    private int householdSize(String householdId) {
650	        if (householdId == null) {
651	            return 1;
652	        }
653	        long existing = this.clinicService.findAllOwners().stream()
654	            .filter(other -> householdId.equals(other.getHouseholdId()))
655	            .count();
656	        return (int) existing + 1;
