659	    /**
660	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
661	     * cannot form a valid E.164 number.
662	     *
663	     * <p>A leading '+' and country code are kept when present; otherwise country code
664	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
665	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
666	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
667	     * exactly the national-digit count that code requires (see
668	     * {@link Owner#hasValidNationalLength}); otherwise it is rejected as invalid.
669	     */
670	    private String toE164(String telephone) {
671	        if (telephone == null) {
672	            return null;
673	        }
674	        boolean hasCountryCode = telephone.trim().startsWith("+");
675	        String digits = telephone.replaceAll("\\D", "");
676	        String e164;
677	        if (hasCountryCode) {
678	            e164 = digits;
679	        } else {
680	            if (digits.startsWith("0")) {
681	                digits = digits.substring(1);
682	            }
683	            e164 = "61" + digits;
684	        }
685	        if (e164.length() < 8 || e164.length() > 15) {
686	            return null;
687	        }
688	        if (!Owner.hasValidNationalLength(e164)) {
689	            return null;
690	        }
691	        return "+" + e164;
692	    }
