694	    /**
695	     * The existing owners already registered in the household identified by {@code householdId}: the
696	     * {@linkplain #activeOwners() active owners} carrying that same non-null householdId. The owner
697	     * being created is not yet persisted, so it is never among them, and a {@code null} householdId
698	     * (an owner with no household) yields an empty collection. This is the single source of a
699	     * household's existing membership, shared by every rule keyed by an owner's household (the
700	     * {@link #membershipLevel(Owner) membership-level} derivation) so the set is never re-derived
701	     * elsewhere; like the other identity rules it ignores {@linkplain Owner#isDeleted() deleted}
702	     * owners.
703	     */
704	    private Collection<Owner> householdMembers(String householdId) {
705	        if (householdId == null) {
706	            return List.of();
707	        }
708	        return activeOwners().stream()
709	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
710	            .collect(Collectors.toList());
711	    }
712	
713	    /**
714	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
715	     * to a single space and lower-case. A null value normalizes to the empty string.
716	     */
717	    private String normalizeName(String value) {
718	        if (value == null) {
719	            return "";
720	        }
721	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
722	    }
723	
724	    /**
725	     * A stable shared identifier for the household an owner belongs to, derived deterministically
726	     * from its lastName and postcode. The lastName is normalized (case-insensitive,
727	     * whitespace-collapsed) before hashing, so every owner sharing the same lastName and postcode is
728	     * assigned the same value regardless of the order in which they are created. Formatted as the
729	     * first 12 upper-case hex characters of the SHA-256 of {@code '<normalizedLastName>|<postcode>'}
730	     * (an absent postcode contributes the empty string).
731	     */
732	    private String householdId(Owner owner) {
733	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
734	        String key = normalizeName(owner.getLastName()) + "|" + postcode;
735	        return shaHexUpper(key).substring(0, 12);
736	    }
737	
738	    /**
739	     * The upper-case rendering of the {@linkplain HashUtils#sha256Hex(String) SHA-256 hex} of
740	     * {@code input} (two hex characters per digest byte, so 64 characters in all). Callers that
741	     * need a shorter opaque token take a prefix of the result (e.g. {@link #householdId} keeps the
742	     * first 12 characters and {@link #customerCode} keeps the first 8). The hashing itself lives in
743	     * {@link HashUtils} so the one implementation is shared with the owner's
744	     * {@link Owner#getIdentityKey() identity key}.
745	     */
746	    private String shaHexUpper(String input) {
747	        return HashUtils.sha256Hex(input).toUpperCase();
748	    }
