750	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
751	    @Override
752	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
753	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
754	        if (currentOwner == null) {
755	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
756	        }
757	        currentOwner.setAddress(ownerFieldsDto.getAddress());
758	        currentOwner.setCity(ownerFieldsDto.getCity());
759	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
760	        currentOwner.setLastName(ownerFieldsDto.getLastName());
761	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
762	        this.clinicService.saveOwner(currentOwner);
763	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
764	    }
765	
766	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
767	    @Transactional
768	    @Override
769	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
770	        Owner owner = this.clinicService.findOwnerById(ownerId);
771	        if (owner == null) {
772	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
773	        }
774	        this.clinicService.deleteOwner(owner);
775	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
776	    }
777	
778	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
779	    @Override
780	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
781	        Owner owner = this.clinicService.findOwnerById(ownerId);
782	        if (owner == null) {
783	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
784	        }
785	        HttpHeaders headers = new HttpHeaders();
786	        Pet pet = petMapper.toPet(petFieldsDto);
787	        owner.setId(ownerId);
788	        pet.setOwner(owner);
789	        pet.getType().setName(null);
790	        this.clinicService.savePet(pet);
791	        PetDto petDto = petMapper.toPetDto(pet);
792	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
793	            .buildAndExpand(pet.getId()).toUri());
794	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
795	    }
796	
797	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
798	    @Override
799	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
800	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
801	        if (currentOwner != null) {
802	            Pet currentPet = this.clinicService.findPetById(petId);
803	            if (currentPet != null) {
804	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
805	                currentPet.setName(petFieldsDto.getName());
806	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
807	                this.clinicService.savePet(currentPet);
808	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
809	            }
810	        }
811	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
812	    }
813	
814	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
815	    @Override
816	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
817	        HttpHeaders headers = new HttpHeaders();
818	        Visit visit = visitMapper.toVisit(visitFieldsDto);
819	        Pet pet = new Pet();
820	        pet.setId(petId);
821	        visit.setPet(pet);
822	        this.clinicService.saveVisit(visit);
823	        VisitDto visitDto = visitMapper.toVisitDto(visit);
824	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
825	            .buildAndExpand(visit.getId()).toUri());
826	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
827	    }
828	
829	
830	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
831	    @Override
832	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
833	        Owner owner = this.clinicService.findOwnerById(ownerId);
834	        if (owner != null) {
835	            Pet pet = owner.getPet(petId);
836	            if (pet != null) {
837	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
838	            }
839	        }
840	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
841	    }
842	}
